<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};

final class WorkflowLanguageService
{
    use TenantOperations;
    public const LANGUAGES=['en'=>'English','zu'=>'isiZulu','af'=>'Afrikaans'];
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    public function preference(): array {return ['language_code'=>$this->db->fetch('SELECT language_code FROM user_workflow_languages WHERE company_id=:company AND user_id=:actor',['company'=>$this->company(),'actor'=>$this->actor()])['language_code']??'en','languages'=>self::LANGUAGES];}
    private function language(mixed $code): string {if(!is_string($code)||!isset(self::LANGUAGES[$code]))throw HttpException::unprocessable('Choose English, isiZulu or Afrikaans.');return $code;}
    public function setPreference(array $input): array {return $this->atomic(function()use($input){$this->fields($input,['language_code']);$language=$this->language($input['language_code']??null);$keys=['company'=>$this->company(),'actor'=>$this->actor()];$old=$this->db->fetch('SELECT preference_id FROM user_workflow_languages WHERE company_id=:company AND user_id=:actor',$keys);if($old)$this->db->execute('UPDATE user_workflow_languages SET language_code=:language WHERE company_id=:company AND user_id=:actor',$keys+['language'=>$language]);else $this->db->execute('INSERT INTO user_workflow_languages(company_id,user_id,language_code) VALUES(:company,:actor,:language)',$keys+['language'=>$language]);$this->audit->record('workflow_language','selected',$this->actor());return ['language_code'=>$language];});}
    private function source(string $kind,string $id,bool $guard=false,bool $forReview=false): array {
        [$table,$key]=match($kind){'INSTRUCTION'=>['site_instruction_versions','instruction_id'],'INSPECTION_FORM'=>['inspection_form_versions','form_id'],'EMERGENCY_PROCEDURE'=>['emergency_procedures','procedure_id'],'NOTIFICATION'=>['notifications','notification_id'],default=>throw HttpException::unprocessable('Unsupported translatable record.')};$r=$this->row($table,$key,$id);
        if($kind==='NOTIFICATION'){
            if(!$forReview&&(string)($r['recipient_user_id']??'')!==$this->actor()&&(empty($r['recipient_employee_id'])||(string)$r['recipient_employee_id']!==$this->employee()))throw HttpException::notFound('Your notification was not found.');
            $content=['title'=>$r['title'],'message'=>$r['message']];
        }else{
            $this->access->requireSite($r['site_id']);if($guard&&!$this->db->fetch("SELECT shift_assignment_id FROM shift_assignments WHERE company_id=:company AND site_id=:site AND employee_id=:employee AND deleted_at IS NULL AND assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS') AND shift_end_at>=:now AND shift_start_at<=:until",['company'=>$this->company(),'site'=>$r['site_id'],'employee'=>$this->employee(),'now'=>gmdate('Y-m-d H:i:s'),'until'=>gmdate('Y-m-d H:i:s',time()+7*86400)]))throw HttpException::notFound('No assigned duty at this site.');
            $content=match($kind){'INSTRUCTION'=>['title'=>$r['title'],'instructions'=>$r['instructions'],'emergency_contacts'=>$r['emergency_contacts']],'EMERGENCY_PROCEDURE'=>['title'=>$r['title'],'steps'=>json_decode($r['steps_json'],true,512,JSON_THROW_ON_ERROR),'emergency_contacts'=>$r['emergency_contacts'],'assembly_point'=>$r['assembly_point']],default=>['title'=>$r['title'],'labels'=>array_column(json_decode($r['fields_json'],true,512,JSON_THROW_ON_ERROR),'label','key')]};
        }
        return ['content'=>$content,'source_hash'=>hash('sha256',json_encode($content,JSON_THROW_ON_ERROR)),'site_id'=>$r['site_id']??null];
    }
    public function read(array $input,bool $guard=false): array {
        $this->fields($input,['entity_kind','entity_id']);$kind=$this->text($input['entity_kind']??null,30);$id=(string)$this->number($input['entity_id']??null);$source=$this->source($kind,$id,$guard);$language=$this->preference()['language_code'];$translation=$this->db->fetch('SELECT content_json,source_hash,revision,reviewed_at FROM workflow_translations WHERE company_id=:company AND entity_kind=:kind AND entity_id=:id AND language_code=:language',['company'=>$this->company(),'kind'=>$kind,'id'=>$id,'language'=>$language]);$current=$translation&&hash_equals($source['source_hash'],$translation['source_hash']);
        return ['entity_kind'=>$kind,'entity_id'=>$id,'requested_language'=>$language,'display_language'=>$language!=='en'&&$current?$language:'en','fallback'=>$language!=='en'&&!$current,'source_hash'=>$source['source_hash'],'translation_revision'=>$translation['revision']??0,'content'=>$language!=='en'&&$current?json_decode($translation['content_json'],true,512,JSON_THROW_ON_ERROR):$source['content'],'source_content'=>$source['content'],'note'=>'Translations are reviewed company content. Missing or stale translations fall back to the original English content.'];
    }
    public function reviewSource(array $input): array {
        $this->fields($input,['entity_kind','entity_id','language_code']);$kind=$this->text($input['entity_kind']??null,30);$id=(string)$this->number($input['entity_id']??null);$language=$this->language($input['language_code']??null);$source=$this->source($kind,$id,false,true);$translation=$this->db->fetch('SELECT revision,content_json FROM workflow_translations WHERE company_id=:company AND entity_kind=:kind AND entity_id=:id AND language_code=:language',['company'=>$this->company(),'kind'=>$kind,'id'=>$id,'language'=>$language]);$this->audit->record('workflow_translation','source_reviewed',$id,[],[],['kind'=>$kind,'language'=>$language]);return ['source_content'=>$source['content'],'source_hash'=>$source['source_hash'],'requested_language'=>$language,'translation_revision'=>(int)($translation['revision']??0),'translated_content'=>$translation?json_decode($translation['content_json'],true,512,JSON_THROW_ON_ERROR):null];
    }
    public function notifications(): array {$user=$this->row('users','user_id',$this->actor());$rows=$this->db->fetchAll('SELECT notification_id,severity,read_at,created_at FROM notifications WHERE company_id=:company AND (recipient_user_id=:actor OR recipient_employee_id=:employee) ORDER BY notification_id DESC LIMIT 100',['company'=>$this->company(),'actor'=>$this->actor(),'employee'=>$user['employee_id']??null]);foreach($rows as&$r)$r['translation']=$this->read(['entity_kind'=>'NOTIFICATION','entity_id'=>$r['notification_id']]);unset($r);return $rows;}
    public function publish(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['entity_kind','entity_id','language_code','expected_source_hash','expected_revision','content']);$kind=$this->text($input['entity_kind']??null,30);$id=(string)$this->number($input['entity_id']??null);$language=$this->language($input['language_code']??null);if($language==='en')throw HttpException::unprocessable('Edit English in its source workflow.');$source=$this->source($kind,$id,false,true);if(!is_string($input['expected_source_hash']??null)||!hash_equals($source['source_hash'],$input['expected_source_hash']))throw HttpException::conflict('The source changed; review the current content.');$content=$input['content']??null;if(!is_array($content)||array_diff(array_keys($content),array_keys($source['content']))||array_diff(array_keys($source['content']),array_keys($content)))throw HttpException::unprocessable('Translate every source field, without adding fields.');
        foreach($source['content']as$key=>$value){if(is_array($value)){if(!is_array($content[$key])||array_keys($value)!==array_keys($content[$key]))throw HttpException::unprocessable('Preserve all step numbers and inspection field keys.');foreach($content[$key]as&$text)$text=$this->text($text,1000);unset($text);}else $content[$key]=$this->text($content[$key],$key==='instructions'?16000:($key==='emergency_contacts'?4000:2000));}
        $keys=['company'=>$this->company(),'kind'=>$kind,'id'=>$id,'language'=>$language];$old=$this->db->fetch('SELECT revision FROM workflow_translations WHERE company_id=:company AND entity_kind=:kind AND entity_id=:id AND language_code=:language',$keys);if($this->number($input['expected_revision']??null,0)!==(int)($old['revision']??0))throw HttpException::conflict('Translation changed.');$values=$keys+['hash'=>$source['source_hash'],'content'=>json_encode($content,JSON_THROW_ON_ERROR),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')];
        if($old)$this->db->execute('UPDATE workflow_translations SET source_hash=:hash,content_json=:content,revision=revision+1,reviewed_by_user_id=:actor,reviewed_at=:now WHERE company_id=:company AND entity_kind=:kind AND entity_id=:id AND language_code=:language',$values);else $this->db->execute('INSERT INTO workflow_translations(company_id,entity_kind,entity_id,language_code,source_hash,content_json,reviewed_by_user_id,reviewed_at) VALUES(:company,:kind,:id,:language,:hash,:content,:actor,:now)',$values);$this->audit->record('workflow_translation','reviewed',$id,[],[],['kind'=>$kind,'language'=>$language]);return ['revision'=>(int)($old['revision']??0)+1];
    });}
}
